function enterHouse(id){dismissWelcome();interior(id);toast(id==='home'?'Shoes off. Shoulders down. You’re home.':`“Come in, come in!” — ${houseDefs.find(h=>h.id===id).name}`);}
function leaveHouse(){const h=houseDefs.find(h=>h.id===state.scene);buildGali();if(h){player.g.position.copy(doorstep(h,8.4));theta=h.rot+Math.PI;camTarget.copy(player.g.position);}toast('Back in the gali. Follow the lights.');}
function giftVisitor(){modal('HAPPY DIWALI!','Look who’s here.','Neha arrives with a box of mithai. “We couldn’t celebrate without stopping by. Also—Sharma Uncle says the cards table is waiting for you!”',choices([['🎁',state.gift?`Give ${state.gift}`:'Choose a gift for Neha','A little something to take home.'],['♠','Visit the cards house','bkhh, across the gali.']]));onChoices(i=>{if(i===1){closeModal();enterHouse('sharma');}else if(state.gift){const gift=state.gift;state.gift=null;closeModal();memory('gift',`“${gift}! You remembered. Happy Diwali!” — Neha`);chime();}else giftDialog();});}
function giftDialog(){modal('DON’T GO EMPTY-HANDED','A little something.','Choose a gift, then give it to a neighbour in the gali. The best part is the visit.',choices([['🎁','Soan papdi','The legendary travelling Diwali box.'],['◇','Kaju katli','A silver-topped box of everyone’s favourite.'],['🟡','Motichoor laddoo','Golden, fragrant, and made for sharing.'],['🎀','A wrapped surprise','Something thoughtful, tied with a ribbon.']]));onChoices(i=>{state.gift=['Soan papdi','Kaju katli','Motichoor laddoo','a wrapped surprise'][i];save();closeModal();toast(`${state.gift} packed. Find Neha near the entrance of the gali to give it to her.`);});}
function rangoliDialog(r=nearest?.obj){modal('COLOUR AT THE DOORSTEP','Make a little beauty.','Riya makes room beside her. “There’s no wrong way. Just pick the colours that feel like Diwali.”',choices([['✿','Marigold & rose','Saffron, coral, and a little peacock blue.'],['❀','Gulabi shaam','Rose, lavender, and soft gold.'],['✺','The one Maa makes','Orange, rice-white, and fresh leaf green.']]));onChoices(i=>{state.rangoliPalette=i;const rr=rangolis.includes(r)?r:rangolis[0];if(rr){rr.material.map.dispose();rr.material.map=rangoliTexture(i);rr.material.needsUpdate=true;}closeModal();memory('rangoli','A little imperfect. Entirely yours. Riya adds one last white dot.');chime();});}
function flowerDialog(){modal('A STRING OF SUNSHINE','Pass the marigolds.','“One orange, one yellow. Just like that.” Aunty shows you how to thread the flowers into a toran.',choices([['🌼','String a marigold toran','Add a fresh garland to your doorway.']]));onChoices(()=>{closeModal();if(state.scene==='gali'){const home=world.children.find(g=>g.userData.houseId==='home');if(home)toran(0,3.6,5.3,3,home);}else toran(0,3.8,-8.4,8);memory('flowers','The marigolds smell like every Diwali you remember.');chime();});}
function cleanDialog(){modal('THE MORNING RITUAL','“A little to the left, beta!”','Rohan balances on the stool while Maa supervises the fan cleaning. “Every Diwali, he suddenly forgets how dusting works.”',choices([['🧹','Pass Rohan the clean cloth','The fan is switched off. Maa keeps the stool steady.']]));onChoices(()=>{closeModal();memory('clean','Fan dusted. Maa approves. Rohan says you owe him a laddoo.');people.filter(p=>p.mode==='clean').forEach(p=>{p.arms[0].rotation.x=-2.3;p.arms[1].rotation.x=-1.8;});chime();});}
function lightsDialog(){modal('PAPA’S ANNUAL PROJECT','“Now switch them on!”','Papa untangles the last loop while Tara holds the string. A whole afternoon for these tiny, perfect lights.',choices([['✧','Switch on the fairy lights','Watch the whole string come alive.']]));onChoices(()=>{closeModal();memory('lights','Tara claps. Papa steps back to admire his masterpiece.');bulbs.forEach(b=>b.material.emissiveIntensity=2.5);chime();});}
function poojaDialog(){if(state.scene!=='home'){enterHouse('home');}if(state.hour<20){modal('EVERYONE WILL BE HERE','Pooja is at 8:00 PM.','The thali is ready. Maa is putting the last flowers by the mandir. You can explore until then, or let the evening come.',choices([['☾','Let it be 8 o’clock','Gather the family for the evening pooja.'],['✿','I’ll come back in a bit','There’s still a whole gali to visit.']]));onChoices(i=>{closeModal();if(i===0){setTime(20);poojaDialog();}});return;}
if(!family.length)interior('home');
modal('8:00 PM · AT HOME','Come. Everyone’s here.','The bell rings. The diyas flicker. For a little while, the whole house grows quiet together.',choices([['🪔','Light the aarti diya','Join the family around the mandir.']]));onChoices(()=>{closeModal();state.pooja=true;player.g.position.set(5,0,4.2);theta=0;pitch=.15;player.g.rotation.y=Math.PI;family.forEach((p,i)=>{p.g.position.set(3.5+(i%2)*1.7,0,1.1+Math.floor(i/2)*1.8);p.g.rotation.y=Math.PI;});for(let i=0;i<9;i++)setTimeout(()=>chime(440+i%3*110,2.4),i*650);memory('pooja','The aarti begins. A warm light on every familiar face.');setTimeout(()=>toast('Maa: “Prasad first. Then everyone on the sofa—dinner is ready.”'),7000);});}
function foodDialog(){modal('MAA MADE YOUR FAVOURITES','Dinner tastes like home.','A plate on your lap. Someone asks for the pickle. Papa insists there’s room for one more poori.',`<div class="menu-item">Aloo sabzi & hot pooris <span>the festive favourite</span></div><div class="menu-item">Paneer, jeera rice & dal <span>seconds encouraged</span></div><div class="menu-item">Boondi raita & achar <span>just a little more</span></div><div class="menu-item">Kheer & gulab jamun <span>save some room</span></div><button class="primary" id="dinnerButton" style="margin-top:22px">Sit with everyone <span>↗</span></button>`);$('#dinnerButton').onclick=()=>{closeModal();if(state.hour<20){setTime(20.5);}if(state.scene!=='home')enterHouse('home');if(!family.length)interior('home');state.dinner=true;const seats=[[-4.25,.65,-.05],[-2.85,.65,-.05],[-1.5,.65,-.05],[-7,.65,3.2]];family.forEach((p,i)=>{p.g.position.set(seats[i][0],0,seats[i][2]);p.opts.seatHeight=.655;p.g.rotation.y=i===3?Math.PI/2:0;p.legs.forEach(l=>l.rotation.x=-1.25);p.mode='seated';foodPlate(0,.38,.8,p.g);});player.g.position.set(-6,.35,3.3);theta=-Math.PI/2;pitch=.15;player.g.rotation.y=Math.PI/2;player.legs.forEach(l=>l.rotation.x=-1.25);memory('dinner','“Another poori?” You haven’t even finished the first one.');chime();};}
function burst(pos,n,color,speed,life,up=false){for(let i=0;i<n;i++){const m=ball(color,0,0,0,rand(.025,.065),scene,true);m.position.copy(pos);particles.push({mesh:m,velocity:v(rand(-1,1)*speed,up?rand(2,5):rand(-1,1)*speed,rand(-1,1)*speed),life,max:life});}}
let audioContext=null,soundEnabled=false,musicTimer;
function chime(freq=660,duration=.9){if(!soundEnabled||!audioContext)return;const now=audioContext.currentTime;for(const [mult,gain] of [[1,.1],[2.01,.025],[3.1,.008]]){const osc=audioContext.createOscillator(),vol=audioContext.createGain();osc.type='sine';osc.frequency.value=freq*mult;vol.gain.setValueAtTime(0,now);vol.gain.linearRampToValueAtTime(gain,now+.01);vol.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(vol).connect(audioContext.destination);osc.start(now);osc.stop(now+duration+.1);}}
$('#sound').onclick=()=>{soundEnabled=!soundEnabled;if(soundEnabled){audioContext||=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();chime(220,4);let n=0;const notes=[220,330,293.66,261.63,196,261.63,293.66,330];musicTimer=setInterval(()=>{chime(notes[n++%notes.length],3);},2400);}else clearInterval(musicTimer);$('#soundState').textContent=soundEnabled?'on':'off';$('#sound').setAttribute('aria-label',soundEnabled?'Mute ambient music':'Enable ambient music');};
