function activityUI(eyebrow,title,text,button,stage=0,total=6,hint='Click the object or use the button.'){document.body.classList.add('busy');$('#activityPanel').hidden=false;$('#activityEyebrow').textContent=eyebrow;$('#activityTitle').textContent=title;$('#activityText').textContent=text;$('#activityButton').textContent=button;$('#activityButton').disabled=false;$('#activitySteps').innerHTML=Array.from({length:total},(_,i)=>`<span class="${i<stage?'done':i===stage?'current':''}"></span>`).join('');$('#activityHint').textContent=hint;$('#holdTrack').hidden=true;}
function focusOn(pos,look){focusView={pos:pos.clone(),look:look.clone()};keys.clear();target=null;player.g.visible=false;}
function clearHeld(){if(heldObject){camera.remove(heldObject);heldObject=null;}}
function endActivity(){if(activity?.type==='diya'&&activity.stage===6&&!activity.completed){const s=activity.station;s.lamp.removeFromParent();s.g.add(s.lamp);s.lamp.position.set(0,.91,0);s.lamp.scale.setScalar(1.4);lightLamp(s.lamp,false);}if(activity?.type==='cracker'){activity.fuseLight?.removeFromParent();activity.matchObject?.removeFromParent();if(activity.stage<3)activity.model.removeFromParent();}if(activity?.type==='poker'){leavePoker();return;}activity=null;focusView=null;holdDown=false;suppressHoldClick=false;holdAmount=0;$('#activityPanel').hidden=true;document.body.classList.remove('busy');clearHeld();player.g.visible=viewMode==='overview';}
$('#activityExit').onclick=endActivity;
