function startDiya(station=diyaStation){if(!station)return;if(activity)endActivity();dismissWelcome();activity={type:'diya',stage:0,station,t:0};activityClock=0;lightLamp(station.lamp,false);station.lamp.userData.lamp.oil.visible=false;station.wick.visible=false;station.match.visible=false;const p=positionOf(station.g);player.g.position.set(p.x,0,p.z+1.65);focusOn(p.clone().add(v(.1,1.65,1.65)),p.clone().add(v(0,.88,0)));renderDiyaStep();}
const diyaSteps=[['A diya, before the light.','Pick a terracotta diya from the thali. Its place will be beside the front door.','Take the clay diya'],['A little oil.','Lift the brass bottle and pour a little oil into the bowl.','Pour the oil'],['The cotton wick.','Set the cotton wick into the oil, leaving its tip over the edge.','Place the wick'],['Strike a match.','Hold the button as the match slides across the side of the box.','Hold to strike'],['Touch the wick.','Bring the match to the cotton. Give the flame a moment to catch.','Light the diya'],['Carry the light home.','Cup the diya in your hands. A place is waiting beside the doorway.','Pick up the diya'],['At the doorstep.','Carry your diya to one of the marked places by the door.','Walk to the doorstep']];
function renderDiyaStep(){const a=activity;if(!a||a.type!=='diya')return;const s=diyaSteps[a.stage];activityUI('THE LITTLE RITUAL · YOUR DIYA',...s,a.stage,7,a.stage===3?'Keep holding for a moment. You can also hold Space.':a.stage===6?'WASD to walk · E to place when you reach the doorway.':'The objects on the tray change with every step.');$('#holdTrack').hidden=a.stage!==3;}
function stepDiya(){const a=activity;if(!a||a.type!=='diya')return;const s=a.station;if(a.stage===3)return;if(a.stage===0){s.lamp.rotation.y=.15;chime(440,.25);}if(a.stage===1){s.lamp.userData.lamp.oil.visible=true;a.pour=1;}if(a.stage===2)s.wick.visible=true;if(a.stage===4){a.ignite=.7;$('#activityButton').disabled=true;return;}if(a.stage===5){takeInHand(s.lamp);focusView=null;theta=Math.PI/2;pitch=.25;}
if(a.stage===6){const index=doorwaySlots().findIndex((_,i)=>!litSlots[state.scene+':'+i]);const i=index<0?0:index;const pos=doorwaySlots()[i];target={pos:pos.clone(),item:{range:2,action:()=>placeDiya(i)}};return;}a.stage++;renderDiyaStep();}
function placeDiya(i){if(activity?.type!=='diya'||activity.stage!==6)return;const pos=doorwaySlots()[i];if(player.g.position.distanceTo(v(pos.x,0,pos.z))>2.4){toast('Bring the diya a little closer to the doorway.');return;}const lamp=activity.station.lamp;lamp.removeFromParent();world.add(lamp);lamp.position.copy(pos);lamp.rotation.set(0,0,0);lamp.scale.setScalar(1);litSlots[state.scene+':'+i]=true;saveLamps();activity.completed=true;endActivity();theta=Math.atan2(-(pos.x-player.g.position.x),-(pos.z-player.g.position.z));pitch=.95;memory('diya','You set the diya by the door. Now this little light belongs here.');const station=diyaStation;if(station){station.lamp=diya(0,0,station.g,.91,false);station.lamp.scale.setScalar(1.4);station.lamp.userData.lamp.oil.visible=false;station.wick.visible=false;}chime();}
function findDiyaTray(){if(state.scene!=='gali'&&!diyaStation){enterHouse('home');}if(!diyaStation)return;const p=positionOf(diyaStation.g);target={pos:p,item:{range:2.6,action:()=>startDiya(diyaStation)}};dismissWelcome();toast('The diya tray is beside the doorway. Walking over…');}
