 pokerPending=pokerSnapshot(tableGame);pokerQueue=pokerSequence(before,pokerPending);const fresh=!before||before.hand!==pokerPending.hand;if(fresh)pokerPotTokens=[];
 pokerDisplay=fresh?{...structuredClone(pokerPending),board:[],pot:0,stage:'dealing',revealed:false,players:pokerPending.players.map((p,i)=>({...p,cards:[],stack:p.stack+p.total-(pokerPending.awards.find(a=>a.seat===i)?.amount||0),total:0,folded:!p.cards.length,last:''}))}:structuredClone(before);
