 if(event.type==='deal'||event.type==='board'||event.type==='burn'){from=deckPoint();to=event.type==='deal'?seatPoint(event.seat,.97,(event.round-.5)*.19):event.type==='board'?v(-.44+event.index*.22,.826,.18):v(-.64,.83,-.24);card=tableCard(null,0,0,0,group);card.position.y=0;}
 else if(event.type==='bet'){pokerDisplay.players[event.seat].stack-=event.amount;refreshPokerTable();pokerVisual.add(group);chips(0,0,event.amount,group,0);from=seatPoint(event.seat,1.04,.27,.84);to=v(0,.88,-.37);}
 else if(event.type==='award'){pokerDisplay.pot-=event.amount;pokerPotTokens=chipTokens(pokerDisplay.pot);refreshPokerTable();pokerVisual.add(group);chips(0,0,event.amount,group,0);from=v(0,.92,-.37);to=seatPoint(event.seat,1.04,.27,.84);}
